cd /tmp/vally-eval-0vIl45 && cat > checkout.mjs <<'EOF'
// PROVISIONAL: product has not decided expired-promotion behavior.
// Chosen: require customer confirmation. Change only EXPIRED_PROMOTION_POLICY.
export const EXPIRED_PROMOTION_POLICY = 'confirm';

const isExpired = (promotion, now) => new Date(promotion.expiresAt) <= now;

export function checkout({ items, promotion, confirmedWithoutPromotion = false }, now = new Date()) {
  const subtotal = items.reduce((sum, i) => sum + i.price * i.quantity, 0);
  const expired = promotion && isExpired(promotion, now);

  if (!promotion || !expired) {
    const discount = promotion ? Math.round(subtotal * promotion.percentOff) / 100 : 0;
    return { status: 'placed', subtotal, discount, total: subtotal - discount };
  }

  switch (EXPIRED_PROMOTION_POLICY) {
    case 'reject':
      return { status: 'rejected', reason: 'promotion_expired' };
    case 'ignore':
      return { status: 'placed', subtotal, discount: 0, total: subtotal };
    default:
      if (confirmedWithoutPromotion) {
        return { status: 'placed', subtotal, discount: 0, total: subtotal };
      }
      return { status: 'confirmation_required', reason: 'promotion_expired', subtotal, total: subtotal };
  }
}
EOF
cat > checkout.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { checkout } from './checkout.mjs';

const now = new Date('2026-11-25T12:00:00Z');
const items = [{ price: 50, quantity: 2 }];
const valid = { percentOff: 10, expiresAt: '2026-12-01T00:00:00Z' };
const expired = { percentOff: 10, expiresAt: '2026-11-01T00:00:00Z' };

test('valid promotion is applied', () => {
  assert.deepEqual(checkout({ items, promotion: valid }, now),
    { status: 'placed', subtotal: 100, discount: 10, total: 90 });
});

test('no promotion places order at full price', () => {
  assert.equal(checkout({ items }, now).total, 100);
});

test('expired promotion requires confirmation and places no order', () => {
  const r = checkout({ items, promotion: expired }, now);
  assert.equal(r.status, 'confirmation_required');
  assert.equal(r.reason, 'promotion_expired');
  assert.equal(r.total, 100);
});

test('confirmed expired promotion places order without discount', () => {
  const r = checkout({ items, promotion: expired, confirmedWithoutPromotion: true }, now);
  assert.deepEqual(r, { status: 'placed', subtotal: 100, discount: 0, total: 100 });
});

test('promotion expiring exactly now is expired', () => {
  const p = { percentOff: 10, expiresAt: now.toISOString() };
  assert.equal(checkout({ items, promotion: p }, now).status, 'confirmation_required');
});
EOF
node --test 2>&1 | tail -8

